import test from 'node:test';
import assert from 'node:assert/strict';
import {Catalog} from '/workspace/src/index.mjs';

test('locale and key lookup is case-sensitive and ignores inherited properties', () => {
  const localePrototype = {inheritedLocale: {label: 'inherited'}};
  const messages = Object.create(localePrototype);
  messages.EN = Object.assign(Object.create({inheritedKey: 'inherited'}), {Label: 'upper'});
  messages.en = {label: 'lower'};
  const catalog = new Catalog(messages, 'en');

  assert.equal(catalog.get('EN', 'Label'), 'upper');
  assert.equal(catalog.get('en', 'Label'), 'Label');
  assert.equal(catalog.get('en', 'inheritedKey'), 'inheritedKey');
  assert.equal(catalog.get('inheritedLocale', 'label'), 'label');
});

