import test from 'node:test';
import assert from 'node:assert/strict';
import {Catalog} from '/workspace/src/index.mjs';

test('get tries the requested locale and its progressively shortened parents before fallback', () => {
  const catalog = new Catalog({
    en: {label: 'fallback'},
    pt: {label: 'root'},
    'pt-BR': {label: 'parent'},
    'pt-BR-x-private': {label: 'exact'},
  }, 'en');

  assert.equal(catalog.get('pt-BR-x-private', 'label'), 'exact');
  assert.equal(catalog.get('pt-BR-x-other', 'label'), 'parent');
  assert.equal(catalog.get('pt-BR-y-other', 'label'), 'parent');
  assert.equal(catalog.get('pt-ZZ-x', 'label'), 'root');
});

