import test from 'node:test';
import assert from 'node:assert/strict';
import {Catalog, translate} from '/workspace/src/index.mjs';

test('translate inherits get behavior without mutating catalog inputs or arguments', () => {
  const messages = {
    'de-DE': {title: ''},
    de: {title: 'Deutsch'},
  };
  const beforeMessages = JSON.stringify(messages);
  const catalog = new Catalog(messages, 'de');
  const locale = 'de-DE';
  const key = 'title';

  assert.equal(translate(catalog, locale, key), '');
  assert.equal(JSON.stringify(messages), beforeMessages);
  assert.equal(locale, 'de-DE');
  assert.equal(key, 'title');
});

